alter table public.timeline_daw_normalization_render_jobs add column if not exists lease_token text,add column if not exists lease_owner text,add column if not exists lease_expires_at timestamptz,add column if not exists heartbeat_at timestamptz,add column if not exists recipe_checksum text,add column if not exists artifact_rms double precision check(artifact_rms>=0),add column if not exists completed_at timestamptz;
create or replace function public.claim_timeline_daw_normalization_render(p_session_id text,p_revision integer,p_worker text,p_lease_token text,p_lease_seconds integer default 60) returns setof public.timeline_daw_normalization_render_jobs language plpgsql security invoker set search_path=public as $$ begin return query update public.timeline_daw_normalization_render_jobs j set state='rendering',lease_token=p_lease_token,lease_owner=p_worker,lease_expires_at=now()+make_interval(secs=>greatest(15,least(p_lease_seconds,300))),heartbeat_at=now(),attempt=j.attempt+1,updated_at=now() where j.id=(select x.id from public.timeline_daw_normalization_render_jobs x where x.owner_id=auth.uid() and x.session_id=p_session_id and x.revision=p_revision and not x.cancel_requested and x.artifact_checksum is null and (x.state in('queued','failed') or (x.state='rendering' and x.lease_expires_at<now())) order by x.created_at for update skip locked limit 1) returning j.*; end $$;
grant execute on function public.claim_timeline_daw_normalization_render(text,integer,text,text,integer) to authenticated;
create index if not exists timeline_daw_normalization_claimable on public.timeline_daw_normalization_render_jobs(owner_id,session_id,revision,state,lease_expires_at) where artifact_checksum is null;